local strings = {
    [SI_BAV_PANEL_NAME] = "Bureau of Acceptable Views",
    [SI_BAV_PANEL_DISPLAY_NAME] = "|c6FCB9FBureau|r of Acceptable Views",
    [SI_BAV_PANEL_INTRO] = "|c6FCB9FАдаптивное управление камерой|r для ситуаций, когда ESO обычно ограничивает зум. Bureau of Acceptable Views делает переход между видом от первого и от третьего лица более предсказуемым, плавным и удобным.",
    [SI_BAV_PANEL_OVERVIEW] = "|c8C8A82• Работает верхом, в воде и в особых формах\n• Запоминает предпочитаемую дистанцию от третьего лица\n• Может сохранять вид от первого лица между релогами и сменой зон\n• Бинды позволяют на ходу сдвигать камеру по горизонтали и вертикали\n• Поддерживает быструю настройку через чат-команды|r",
    [SI_BAV_HEADER_CAMERA] = "|cC5C29EТонкая настройка камеры|r",
    [SI_BAV_HEADER_OFFSET_NUDGE] = "|cC5C29EЖивое смещение кадра|r",
    [SI_BAV_SECTION_OFFSET_NUDGE_DESCRIPTION] = "|c8C8A82Бинды смещения заблокированы, пока вы не запомните одно исходное положение кнопкой ниже. После этого удерживайте клавиши, чтобы сдвигать камеру влево, вправо, вверх или вниз, а восстановление всегда возвращает именно к этому кадру. Смещение само дом не перезаписывает. Назначьте клавиши в «Управление» -> Bureau of Acceptable Views. Плечо, зум и поле зрения эти бинды не трогают.|r",
    [SI_BAV_SETTING_OFFSET_NUDGE_SPEED_NAME] = "Скорость смещения",
    [SI_BAV_SETTING_OFFSET_NUDGE_SPEED_TOOLTIP] = "Насколько быстро камера едет, пока бинд зажат. 100% - отзывчивое значение по умолчанию. Меньше - ближе к покадровому nudging старых аддонов; больше - быстрее доходит до предела движка. Неактивно, пока не запомнено исходное положение.",
    [SI_BAV_SETTING_OFFSET_NUDGE_OVERLAY_NAME] = "Показывать уведомления на экране",
    [SI_BAV_SETTING_OFFSET_NUDGE_OVERLAY_TOOLTIP] = "Показывать в верхней части экрана смещение, а также сообщения о запоминании, восстановлении и удалении исходного положения. После последнего ввода плашка держится ещё две секунды и скрывается.",
    [SI_BAV_SETTING_OFFSET_HOME_STATUS_NONE] = "|c8C8A82Исходное положение: не запомнено. Бинды не будут двигать камеру, пока вы его не сохраните.|r",
    [SI_BAV_SETTING_OFFSET_HOME_STATUS_SET] = "|c6FCB9FИсходное положение запомнено.|r Горизонталь %s   Вертикаль %s",
    [SI_BAV_SETTING_OFFSET_HOME_REMEMBER_NAME] = "Запомнить текущую камеру",
    [SI_BAV_SETTING_OFFSET_HOME_REMEMBER_TOOLTIP] = "Сохранить текущие горизонтальное и вертикальное смещения как единственное исходное положение. Если активен контекстный пресет, запоминается ваш реальный кадр, а не кинематографический оверлей. Заменяет предыдущее исходное положение.",
    [SI_BAV_SETTING_OFFSET_HOME_RESTORE_NAME] = "Восстановить исходное положение",
    [SI_BAV_SETTING_OFFSET_HOME_RESTORE_TOOLTIP] = "Вернуть живую камеру к запомненному исходному положению. Ничего не делает, пока дом не сохранён.",
    [SI_BAV_SETTING_OFFSET_HOME_CLEAR_NAME] = "Удалить исходное положение",
    [SI_BAV_SETTING_OFFSET_HOME_CLEAR_TOOLTIP] = "Забыть запомненный кадр. Бинды снова блокируются, пока вы не запомните новый. Живую камеру не меняет.",
    [SI_BAV_SETTING_OFFSET_HOME_CLEAR_CONFIRM] = "Удалить запомненное исходное положение? Бинды перестанут двигать камеру, пока вы не запомните новое.",
    [SI_BAV_NUDGE_OVERLAY_HORIZONTAL] = "Горизонталь",
    [SI_BAV_NUDGE_OVERLAY_VERTICAL] = "Вертикаль",
    [SI_BAV_NUDGE_OVERLAY_CENTER] = "центр",
    [SI_BAV_NUDGE_OVERLAY_PERCENT] = "%d%%",
    [SI_BAV_NUDGE_OVERLAY_LIVE] = "Живое смещение",
    [SI_BAV_NUDGE_OVERLAY_BLOCKED] = "Исходное положение не запомнено.\nСохраните его в Настройки -> Дополнения\n-> Bureau of Acceptable Views -> Живое смещение кадра.",
    [SI_BAV_NUDGE_OVERLAY_FAILED] = "Изменение камеры сейчас недоступно.\nВозможно, камерой управляет ESO.",
    [SI_BAV_NUDGE_OVERLAY_REMEMBERED] = "Исходное положение запомнено",
    [SI_BAV_NUDGE_OVERLAY_CLEARED] = "Исходное положение удалено",
    [SI_BAV_NUDGE_OVERLAY_RESTORED] = "Камера восстановлена",
    [SI_BINDING_CATEGORY_BAV] = "Bureau of Acceptable Views",
    [SI_BINDING_NAME_BAV_HORIZONTAL_OFFSET_LEFT] = "Горизонтальное смещение влево",
    [SI_BINDING_NAME_BAV_HORIZONTAL_OFFSET_RIGHT] = "Горизонтальное смещение вправо",
    [SI_BINDING_NAME_BAV_VERTICAL_OFFSET_UP] = "Вертикальное смещение вверх",
    [SI_BINDING_NAME_BAV_VERTICAL_OFFSET_DOWN] = "Вертикальное смещение вниз",
    [SI_BINDING_NAME_BAV_OFFSET_RECENTER] = "Восстановить исходное положение",
    [SI_BAV_HEADER_BEHAVIOR] = "|cC5C29EПоведение и сохранение|r",
    [SI_BAV_HEADER_DEBUG] = "Диагностика",
    [SI_BAV_SECTION_CAMERA_DESCRIPTION] = "|c8C8A82Настройте, насколько плавно и быстро ощущается зум, и задайте безопасную резервную дистанцию от третьего лица.|r",
    [SI_BAV_SECTION_BEHAVIOR_DESCRIPTION] = "|c8C8A82Определите, как аддон должен восстанавливать камеру после релогов, смены зон и возврата из первого лица.|r",
    [SI_BAV_SETTING_CAMERA_RESPONSE_NAME] = "Отклик камеры",
    [SI_BAV_SETTING_CAMERA_RESPONSE_TOOLTIP] = "Определяет, как изменения динамического FOV, контекстных пресетов и камеры через плечо достигают цели. «Как в ESO» не вмешивается во встроенное сглаживание камеры. «Моментальная» применяет параметры за один кадр, отключая сглаживание для пресетов и камеры через плечо. «Отзывчивая» использует короткий быстро затухающий переход. «Плавная» использует более долгий кинематографичный переход. Динамический FOV использует выбранные длительность и кривую перехода, не изменяя встроенное сглаживание камеры. Аварийное восстановление, восстановление после загрузки, защита осадной камеры и живое смещение остаются мгновенными.",
    [SI_BAV_SETTING_CAMERA_RESPONSE_NATIVE] = "Как в ESO",
    [SI_BAV_SETTING_CAMERA_RESPONSE_INSTANT] = "Моментальная",
    [SI_BAV_SETTING_CAMERA_RESPONSE_RESPONSIVE] = "Отзывчивая",
    [SI_BAV_SETTING_CAMERA_RESPONSE_SMOOTH] = "Плавная",
    [SI_BAV_SECTION_DEBUG_DESCRIPTION] = "|c8C8A82Полезно для проверки редких случаев и диагностики странного поведения камеры. Для обычной игры лучше держать уровень ниже, чтобы не засорять чат.|r",
    [SI_BAV_HEADER_DYNAMIC_FOV] = "Динамическое поле зрения",
    [SI_BAV_SECTION_DYNAMIC_FOV_DESCRIPTION] = "|c8C8A82Слегка расширяет или сужает поле зрения от третьего лица в зависимости от того, насколько вы отдалили камеру, создавая более кинематографичное ощущение глубины. |r|c6FCB9FВключено по умолчанию.|r",
    [SI_BAV_HEADER_CONTEXT_PRESETS] = "Контекстные пресеты",
    [SI_BAV_SECTION_CONTEXT_PRESETS_DESCRIPTION] = "|c8C8A82Автоматически подстраивают кадрирование камеры под конкретные игровые состояния. Каждое состояние включается отдельно, а общая сила эффекта масштабируется ползунком интенсивности. |r|cD0905EПо умолчанию отключено.|r",
    [SI_BAV_HEADER_PVP_MODE] = "Режим PvP",
    [SI_BAV_SECTION_PVP_MODE_DESCRIPTION] = "|c8C8A82Простой отдельный режим для миров AvA и полей сражений. Он использует отдельный шаг ручного зума и может подавлять дрожание камеры, но никогда автоматически не меняет дистанцию, FOV или смещения камеры. Управление остаётся прямым и полностью под контролем игрока. |r|c6FCB9FВключено по умолчанию.|r",
    [SI_BAV_PVP_TESTING_FEEDBACK_TITLE] = "Тестирование и обратная связь",
    [SI_BAV_PVP_TESTING_FEEDBACK_DESCRIPTION] = "|cD0905EРежим PvP всё ещё находится на стадии тестирования и будет дорабатываться по результатам игры.|r\n\n|cC5C29EОбратная связь игроков важна.|r Если у вас есть конкретные пожелания, основанные на личном опыте, расскажите о них на форуме аддона. Каждое предложение будет изучено, и полезные идеи, соответствующие направлению аддона, могут быть добавлены в одном из будущих обновлений.",
    [SI_BAV_SLASH_HINT] = "|cC5C29EБыстрые команды|r: |cFFFFFF/bav|r  |cC5C29E•|r  |cFFFFFF/bav settings|r  |cC5C29E•|r  |cFFFFFF/bav config|r  |cC5C29E•|r  |cFFFFFF/bav help|r",

    [SI_BAV_STATUS_TITLE] = "|cC5C29EТекущее состояние|r",
    [SI_BAV_STATUS_ON] = "вкл",
    [SI_BAV_STATUS_OFF] = "выкл",
    [SI_BAV_STATUS_CAM_FIRST_PERSON] = "от первого лица",
    [SI_BAV_STATUS_CAM_THIRD_PERSON] = "от третьего лица",
    [SI_BAV_STATUS_SHOULDER_AUTO] = "авто",
    [SI_BAV_STATUS_SHOULDER_MANUAL] = "вручную",
    [SI_BAV_STATUS_LABEL_CAMERA] = "Камера:",
    [SI_BAV_STATUS_LABEL_DYNAMIC_FOV] = "Динамический FOV:",
    [SI_BAV_STATUS_LABEL_PRESETS] = "Контекстные пресеты:",
    [SI_BAV_STATUS_LABEL_SHOULDER] = "Камера через плечо:",
    [SI_BAV_STATUS_LABEL_OFFSET_NUDGE] = "Исходный кадр:",
    [SI_BAV_STATUS_LABEL_PVP_MODE] = "Режим PvP:",

    [SI_BAV_SETTING_ZOOM_STEP_NAME] = "Шаг зума",
    [SI_BAV_SETTING_ZOOM_STEP_TOOLTIP] = "Насколько меняется зум за одно действие. Меньшие значения ощущаются плавнее, большие - быстрее.",
    [SI_BAV_SETTING_THRESHOLD_NAME] = "Порог сохранения зума",
    [SI_BAV_SETTING_THRESHOLD_TOOLTIP] = "Только значения зума от третьего лица выше этого порога запоминаются как предпочтительная дистанция возврата из вида от первого лица.",
    [SI_BAV_SETTING_MIN_MOUNTED_NAME] = "Резервный зум от третьего лица",
    [SI_BAV_SETTING_MIN_MOUNTED_TOOLTIP] = "Резервная дистанция от третьего лица, используемая, когда нет корректного запомненного значения.",
    [SI_BAV_SETTING_PRESERVE_FPV_NAME] = "Сохранять вид от первого лица между релогами и зонами",
    [SI_BAV_SETTING_PRESERVE_FPV_TOOLTIP] = "Если включено, выход из игры или смена зоны в виде от первого лица восстановят его после загрузки. Если выключено, аддон вместо этого вернёт сохранённую дистанцию от третьего лица.",
    [SI_BAV_SETTING_DEBUG_MODE_NAME] = "Режим отладки",
    [SI_BAV_SETTING_DEBUG_MODE_TOOLTIP] = "Управляет объёмом диагностических сообщений, которые аддон выводит в чат.",
    [SI_BAV_SETTING_RESET_CONFIG_NAME] = "Сбросить к нейтральной камере",
    [SI_BAV_SETTING_RESET_CONFIG_TOOLTIP] = "Восстановить основные значения зума и выключить все необязательные функции - для чистой, «ванильной» камеры. Учтите: это не то же самое, что свежая установка - динамический FOV и режим PvP поставляются включёнными, но сброс намеренно выключает обе функции, давая вам нейтральную отправную точку.",
    [SI_BAV_SETTING_RESET_CONFIG_CONFIRM] = "Будут восстановлены основные значения зума и выключены все необязательные функции (динамический FOV, контекстные пресеты, камера через плечо, режим PvP). Ваши изменения будут потеряны. Продолжить?",
    [SI_BAV_SETTING_RESET_CAMERA_NAME] = "Сбросить состояние камеры",
    [SI_BAV_SETTING_RESET_CAMERA_TOOLTIP] = "Немедленно вернуть управление камерой вам: приостановить режим PvP до выхода из текущего PvP-мира, восстановить его значение дрожания камеры, снять активный контекстный пресет и удержание угла обзора, а затем сбросить активное и сохранённое состояние камеры.",
    [SI_BAV_SETTING_RESET_CAMERA_CONFIRM] = "Режим PvP будет приостановлен до выхода из текущего PvP-мира, его значение дрожания камеры будет восстановлено, активный пресет и удержание угла обзора будут сняты, а камера сброшена. Продолжить?",
    [SI_BAV_SETTING_RESET_CAMERA_NOTE] = "|c6FCB9FСтраховка:|r воспринимайте это как ремень безопасности. Аддон очень надёжно работает с настройками и не должен оставлять камеру в некорректном состоянии, так что, скорее всего, это вам никогда не понадобится. Кнопка здесь исключительно ради тех самых 0.001% вероятности - один клик мгновенно вернёт вам полный контроль над камерой.",
    [SI_BAV_SETTING_PRINT_CONFIG_NAME] = "Показать текущую конфигурацию",
    [SI_BAV_SETTING_PRINT_CONFIG_TOOLTIP] = "Вывести текущую конфигурацию аддона в чат.",
    [SI_BAV_HEADER_CONFIGURATION] = "|cC5C29EКонфигурация|r",
    [SI_BAV_SECTION_CONFIGURATION_DESCRIPTION] = "|c8C8A82Просмотрите текущие настройки или сбросьте к нейтральной камере: основные значения зума восстанавливаются, а все необязательные функции выключаются. Сброс затрагивает только конфигурацию аддона и не трогает активную камеру.|r",
    [SI_BAV_HEADER_CAMERA_ACTIONS] = "Управление камерой",
    [SI_BAV_SECTION_CAMERA_ACTIONS_DESCRIPTION] = "|c8C8A82Верните себе управление активной камерой одним кликом, независимо от сохранённой конфигурации.|r",

    [SI_BAV_SETTING_DYNAMIC_FOV_ENABLED_NAME] = "Включить динамическое поле зрения",
    [SI_BAV_SETTING_DYNAMIC_FOV_ENABLED_TOOLTIP] = "Если включено, поле зрения от третьего лица плавно меняется между ближним и дальним значением по мере приближения и отдаления камеры.",
    [SI_BAV_SETTING_DYNAMIC_FOV_SMOOTH_NAME] = "Плавные переходы FOV",
    [SI_BAV_SETTING_DYNAMIC_FOV_SMOOTH_TOOLTIP] = "Если включено, поле зрения не переключается мгновенно между шагами зума, а плавно перетекает к новому значению за долю секунды. Когда вы приближаете или отдаляете камеру, объектив мягко «подъезжает» к целевому FOV по плавной кривой, а не дёргается рывком - это убирает резкие скачки картинки и делает зум заметно более кинематографичным и приятным для глаз. Целевое значение при этом всегда одно и то же: меняется только путь к нему, поэтому на итоговый кадр опция не влияет. Сам переход временный и не нагружает игру в простое.\n\n|c6FCB9FРекомендуется держать включённым:|r это заметно улучшает ощущение от камеры практически без какой-либо платы за производительность.",
    [SI_BAV_SETTING_DYNAMIC_FOV_NEAR_NAME] = "Поле зрения (камера приближена)",
    [SI_BAV_SETTING_DYNAMIC_FOV_NEAR_TOOLTIP] = "Поле зрения, применяемое когда камера приближена до упора. Ограничено допустимым диапазоном FOV движка, поэтому любое значение здесь безопасно.",
    [SI_BAV_SETTING_DYNAMIC_FOV_FAR_NAME] = "Поле зрения (камера отдалена)",
    [SI_BAV_SETTING_DYNAMIC_FOV_FAR_TOOLTIP] = "Поле зрения, применяемое когда камера отдалена до упора. Разведите его дальше от значения приближения для более сильного эффекта, сведите ближе чтобы смягчить, или сделайте равными чтобы полностью убрать эффект.",
    [SI_BAV_SETTING_DYNAMIC_FOV_RESET_NAME] = "Сбросить диапазон FOV",
    [SI_BAV_SETTING_DYNAMIC_FOV_RESET_TOOLTIP] = "Очистить ваши значения ближнего/дальнего FOV и вернуться к стандартному диапазону поля зрения движка.",
    [SI_BAV_SETTING_PRESETS_ENABLED_NAME] = "Включить контекстные пресеты",
    [SI_BAV_SETTING_PRESETS_ENABLED_TOOLTIP] = "Главный переключатель контекстных пресетов. Когда выключен, ни одна из настроек кадрирования по состояниям ниже не применяется.",
    [SI_BAV_LABEL_PRESET_STATES] = "|cC5C29EВыберите стиль для каждого состояния|r",
    [SI_BAV_LABEL_PRESET_STATES_HELP] = "|c8C8A82Выберите «Выключено», чтобы отключить состояние; ползунок интенсивности влияет только на состояния с непустым стилем.|r",
    [SI_BAV_SETTING_PRESET_INTENSITY_NAME] = "Интенсивность пресетов",
    [SI_BAV_SETTING_PRESET_INTENSITY_TOOLTIP] = "Масштабирует, насколько сильно активные пресеты смещают камеру: от 0% (без эффекта) до 100% (полный эффект).",
    [SI_BAV_SETTING_PRESET_STATE_INTENSITY_NAME] = "Интенсивность состояния",
    [SI_BAV_SETTING_PRESET_STATE_INTENSITY_TOOLTIP] = "Масштабирует кадрирование этого состояния поверх общей интенсивности пресетов: от 0% (без эффекта) до 100% (полная сила стиля). Недоступно, когда стиль этого состояния - «Выкл».",
    [SI_BAV_SETTING_PRESET_COALESCE_NAME] = "Задержка возврата",
    [SI_BAV_SETTING_PRESET_COALESCE_TOOLTIP] = "Сколько времени выход из этого состояния ждёт перед возвратом камеры. Небольшая задержка позволяет быстрому выходу-и-возврату (например, бой закончился и тут же начался снова) свестись к нулевому действию вместо рывка камеры. «Выкл» возвращает камеру сразу, без сглаживания. По умолчанию отключено для всех состояний.",
    [SI_BAV_SETTING_PRESET_COALESCE_OFF] = "Выкл",
    [SI_BAV_SETTING_PRESET_COALESCE_MS_FORMAT] = "%d мс",
    [SI_BAV_SETTING_PRESET_COALESCE_S_FORMAT] = "%g с",
    [SI_BAV_SETTING_PRESET_SMOOTH_NAME] = "Плавные переходы пресетов",
    [SI_BAV_SETTING_PRESET_SMOOTH_TOOLTIP] = "Если включено, переключение контекстных пресетов плавно перетекает между кадрированием камеры и полем зрения за долю секунды вместо мгновенного скачка. Чисто косметическая опция.",
